import type { IncomingMessage, ServerResponse } from 'node:http';
import { log } from './log.ts';

/**
 * Logs one line per request once the response is done: method, path, status, duration in ms.
 *
 * Deliberately logs nothing else: no query string, headers or body, because requests carry the
 * recipient's name, address and phone number (personal data, must never be logged). Shipment ids
 * in the path and tracking numbers are fine.
 */
export function logRequest(req: IncomingMessage, res: ServerResponse, pathname: string): void {
  const start = performance.now();
  let logged = false;
  const write = (aborted: boolean) => {
    if (logged) return;
    logged = true;
    log.info('http', {
      method: req.method,
      path: pathname,
      status: res.statusCode,
      duration_ms: Math.round(performance.now() - start),
      ...(aborted ? { aborted: true } : {}),
    });
  };
  res.once('finish', () => write(false));
  // 'close' without 'finish': the client went away before the response was sent
  res.once('close', () => write(true));
}
